-- 공식 공고문(별첨 hwpx 7d313e37) 붙임5 경영개선지원 신청서 · 붙임7 완료보고서 및 지원금 신청서를
-- 원본 표 구조 그대로 재작성. 나머지 붙임 서식(0019·0020)과 동일한 시각 스타일로 정합화.
--   - 맑은 고딕 임베드(render.ts) 사용 → body font-family 미지정(주입 폰트 상속)
--   - 검정 실선 테두리 + 회색(#f2f2f2) 헤더 + 좌측정렬 값칸
-- 서명 플레이스홀더 {{{sign_applicant}}}/{{{sign_consultant}}}/{{{sign_contractor}}} 유지.

-- ── 붙임5 경영개선지원 신청서 (support_application_management) ──────────
update public.document_templates set
  name='경영개선지원 신청서', attachment_no='붙임5',
  html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:14mm 13mm}body{color:#000;font-size:11.5px;line-height:1.5}.top{text-align:center;font-size:11.5px;margin:0}h1{text-align:center;font-size:17px;font-weight:800;margin:2px 0 10px}.sec{font-weight:700;margin:11px 0 4px;font-size:12.5px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3px 0}th,td{border:1px solid #000;padding:5px 7px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center}td{text-align:left}.sub{font-weight:400;font-size:9.5px;color:#333}.chk{letter-spacing:1px}.box{height:44px;vertical-align:top}.photo{height:110px;text-align:center;color:#888;font-size:10.5px;vertical-align:middle}.note{font-size:10px;color:#444;margin:3px 2px}.stmt td{text-align:justify;line-height:1.65}.sign td{text-align:center}.foot{margin-top:6px;text-align:center;font-weight:800;font-size:13px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원사업</p><h1>경영개선지원 신청서</h1><p class="sec">1. 지원업체 현황</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>상시근로자<br><span class="sub">(대표자 제외)</span></th><td>{{employee_count}} 명</td><th>개업연월일</th><td>{{opened_at}}</td></tr><tr><th>업 태</th><td>{{business_type}}</td><th>종 목</th><td>{{item}}</td></tr></table><p class="sec">2. 컨설팅</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>성 명<br><span class="sub">(컨설턴트)</span></th><td>{{consultant_name}}</td><th>연락처<br><span class="sub">(컨설턴트)</span></th><td>{{consultant_phone}}</td></tr><tr><th>컨설팅일자</th><td colspan="3">(1차) {{consulting_date_1}} &nbsp;&nbsp; (2차) {{consulting_date_2}} &nbsp;&nbsp; (3차) {{consulting_date_3}}</td></tr></table><p class="sec">3. 경영개선자금 신청내역</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>총 신청내역</th><td class="chk" colspan="3">{{cat_hygiene}} 위생관리 &nbsp; {{cat_safety}} 안전관리 &nbsp; {{cat_promo}} 홍보(광고) &nbsp; {{cat_env}} 환경개선 &nbsp; {{cat_pos}} POS경비</td></tr><tr><th>총소요비용</th><td colspan="3">※ 지원금 최대 300만원 (부가가치세는 자부담)</td></tr><tr><th>소요금액<br><span class="sub">(부가세 제외)</span></th><td>{{cost_excl_vat}} 원</td><th>지원금신청액<br><span class="sub">(소요금액의 100%)</span></th><td>{{requested_amount}} 원</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{reason}}</td></tr><tr><th>단위사업</th><td></td><th>소요금액<span class="sub">(부가세 제외)</span></th><td> 원</td></tr><tr><th>단위사업</th><td></td><th>소요금액<span class="sub">(부가세 제외)</span></th><td> 원</td></tr><tr><th>단위사업</th><td></td><th>소요금액<span class="sub">(부가세 제외)</span></th><td> 원</td></tr></table><p class="note">* 필요시 칸 추가 기재</p><p class="sec">4. 시공(제작) 내용</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">{{cat_hygiene}} 위생관리 &nbsp; {{cat_safety}} 안전관리 &nbsp; {{cat_promo}} 홍보(광고) &nbsp; {{cat_env}} 환경개선 &nbsp; {{cat_pos}} POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td>{{contractor_name}}</td><th>사업자등록번호</th><td>{{contractor_reg_no}}</td></tr><tr><th>대표자명</th><td>{{contractor_rep}}</td><th>업태/종목</th><td>{{contractor_work_type}}</td></tr><tr><th>사업장 연락처</th><td>{{contractor_phone}}</td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3">{{contractor_work_type}}</td></tr></table><p class="note">* 외주업체가 복수인 경우 필요시 페이지 추가 기재</p><p class="sec">5. 추진계획</p><table><colgroup><col style="width:20%"><col style="width:80%"></colgroup><tr><th>구 분</th><th>주 요 내 용</th></tr><tr><th>사업소개</th><td class="box"></td></tr><tr><th>경영상황</th><td class="box"></td></tr><tr><th>지원 필요성</th><td class="box"></td></tr><tr><th>기대효과</th><td class="box"></td></tr></table><p class="sec">6. 사업장 사진</p><p class="note">* 현재 사업장 내·외부 사진(간판이 보이게 촬영), 시공할 장소 사진</p><table><colgroup><col style="width:50%"><col style="width:50%"></colgroup><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr></table><table style="margin-top:10px"><tr><td class="stmt" style="text-align:justify"><b>(수혜대상(대표자))</b> ▶ 본 참여 신청서 및 공고문의 내용을 모두 확인하고 본인이 직접 서명함을 확인합니다. ▶ 서류 누락 또는 공고문 내용을 위반하는 경우 지원 탈락으로 간주함에 동의합니다.</td></tr></table><table class="sign"><colgroup><col style="width:34%"><col style="width:33%"><col style="width:33%"></colgroup><tr><td rowspan="2">{{application_date}}</td><td>신청업체(대표자) {{owner_name}}</td><td>{{{sign_applicant}}}</td></tr><tr><td>컨설턴트 {{consultant_name}}</td><td>{{{sign_consultant}}}</td></tr></table><p class="foot">{{institution}} 귀하</p><table><colgroup><col style="width:12%"><col style="width:88%"></colgroup><tr><th rowspan="2">첨부서류</th><td>【필수】 외주업체 사업자등록증 사본 1부, 견적서 1부(100만원 이상일 경우 견적서 2개 이상), 사업참여 및 중복지원 금지 확약서</td></tr><tr><td>【해당 시】 옥외광고업 등록증</td></tr></table></body></html>$html$
where template_key='support_application_management';

-- ── 붙임7 경영개선지원 완료보고서 및 지원금 신청서 (payment_application_management) ──
update public.document_templates set
  name='경영개선지원 완료보고서 및 지원금 신청서', attachment_no='붙임7',
  html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:14mm 13mm}body{color:#000;font-size:11.5px;line-height:1.5}.top{text-align:center;font-size:11.5px;margin:0}h1{text-align:center;font-size:16px;font-weight:800;margin:2px 0 10px}.sec{font-weight:700;margin:11px 0 4px;font-size:12.5px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:3px 0}th,td{border:1px solid #000;padding:5px 7px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center}td{text-align:left}.sub{font-weight:400;font-size:9.5px;color:#333}.chk{letter-spacing:1px}.box{height:70px;vertical-align:top}.photo{height:100px;text-align:center;color:#888;font-size:10.5px;vertical-align:top}.note{font-size:10px;color:#444;margin:3px 2px}.oath td{text-align:justify;line-height:1.7;padding:8px}.oath ol{margin:4px 0 0;padding-left:18px}.sign td{text-align:center}.foot{margin-top:6px;text-align:center;font-weight:800;font-size:13px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원사업</p><h1>경영개선지원 완료보고서 및 지원금 신청서</h1><p class="sec">1. 지원업체 현황</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>대표자연락처</th><td>{{phone}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr></table><p class="sec">2. 지원금 신청사항</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>총 신청내역</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>총소요비용</th><td colspan="3">※ 지원금 최대 300만원 / 심의 시 지원금액은 하향 조정될 수 있음</td></tr><tr><th>소요금액 합계<br><span class="sub">(부가세 제외)</span></th><td>{{cost_excl_vat}} 원</td><th>지원금 신청액<br><span class="sub">(소요금액의 100%)</span></th><td>{{amount}} 원</td></tr><tr><th>지원금지급처</th><td colspan="3">※ 반드시 대표자(또는 법인) 본인 명의 통장 기재 (불일치 시 지급 불가)</td></tr><tr><th>은행명</th><td>{{bank_name}}</td><th>예금주</th><td>{{account_holder}}</td></tr><tr><th>계좌번호</th><td colspan="3">{{account_number}}</td></tr><tr><th>신청금액</th><td colspan="3">{{amount}} 원</td></tr><tr><th>시공(제작)<br>완료사항</th><td colspan="3">시공내용(요약)</td></tr><tr><th>단위사업</th><td></td><th>소요금액<span class="sub">(부가세 제외)</span></th><td> 원</td></tr><tr><th>단위사업</th><td></td><th>소요금액<span class="sub">(부가세 제외)</span></th><td> 원</td></tr><tr><th>단위사업</th><td></td><th>소요금액<span class="sub">(부가세 제외)</span></th><td> 원</td></tr></table><p class="note">* 필요시 칸 추가 기재</p><p class="sec">3. 지원사업 결과물</p><p class="note">* 해당내용은 시공(제작)공사 수 만큼 기재 및 첨부(필수)</p><table><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td>{{contractor_name}}</td><th>사업자등록번호</th><td>{{contractor_reg_no}}</td></tr><tr><th>외주업체 대표자명</th><td>{{contractor_rep}}</td><th>업태/종목</th><td>{{contractor_work_type}}</td></tr><tr><th>사업장 연락처</th><td>{{contractor_phone}}</td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3">{{contractor_work_type}}</td></tr></table><table><colgroup><col style="width:50%"><col style="width:50%"></colgroup><tr><th>개선 전</th><th>개선 후</th></tr><tr><td class="photo">(개선 전 결과물 사진)</td><td class="photo">(개선 후 결과물 사진)</td></tr></table><table class="oath" style="margin-top:8px"><tr><td>신청인과 외주업체는 대전일자리경제진흥원(이하 "진흥원")에서 시행하는 『대전 소상공인·자영업자 재기지원사업(컨설팅·경영개선)』에 참여하고 수행함에 있어 다음 의무사항을 성실하게 이행하며, 불이행 시 규정에 따른 불이익을 감수할 것을 확약합니다.<ol><li>신청인은 사업 목적에 맞게 단위사업을 수행하였으며 이에 따른 지원금을 신청한다.</li><li>신청인과 외주업체는 서로 부당한 이익을 제공하지 않는다. - 자부담금 경감, 자부담금 시공사 대납, 서류 대필 및 수수료 요구, 제3자 부당개입 등</li><li>신청인과 외주업체는 과제수행과 관련한 모든 행위에 대하여 위법이나 부당한 사항이 발생된 것에 대해서 모든 책임을 진다. - 신청업체 휴·폐업, 사업장 양도, 부실시공, 관련서류 위·변조, 선정일 이전 과제시행 등</li><li>위 사항을 위반하여 진흥원으로부터 사업 참여 제한, 지원금 환수 등 제재조치를 받을 수 있으며, 이에 대해 일체의 이의를 제기하지 않음을 확인한다.</li></ol></td></tr></table><table class="sign"><colgroup><col style="width:34%"><col style="width:33%"><col style="width:33%"></colgroup><tr><td rowspan="3">{{application_date}}</td><td>신청업체(대표자) {{owner_name}}</td><td>{{{sign_applicant}}}</td></tr><tr><td>외주업체 대표 {{contractor_rep}}</td><td>{{{sign_contractor}}}</td></tr><tr><td>컨설턴트 {{consultant_name}}</td><td>{{{sign_consultant}}}</td></tr></table><p class="foot">{{institution}} 귀하</p><table><colgroup><col style="width:12%"><col style="width:88%"></colgroup><tr><th rowspan="2">첨부서류</th><td>【필수】 통장사본(대표자 명의), 외주업체 사업자등록증 사본, 전자세금계산서, 하자보증이행각서, 지출 증빙자료(계좌이체 입금증 또는 이체(송금)확인증)</td></tr><tr><td>【해당 시】 옥외광고물 등 표시 신고증명서 또는 옥외광고물 표시 신고(허가) 비대상 확인서, 영상정보처리기기 운영·관리 방침</td></tr></table></body></html>$html$
where template_key='payment_application_management';
